__NUXT_JSONP__("/think-tanks/eventos/ethos_comparte_aprendizajes_sobre_sostenibilidad_financiera_en_la_ott_conference_2026", (function(a,b,c,d,e,f,g){return {data:[{post:{slug:"ethos_comparte_aprendizajes_sobre_sostenibilidad_financiera_en_la_ott_conference_2026",title:"Ethos comparte aprendizajes sobre sostenibilidad financiera en la OTT Conference 2026",date:"2026-06-18T17:24:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Fe6f747e1-817d-40e7-ad9c-3bd1df3c97c7\u002F","img-alt":"OTT Conference 2026",autor:"Ethos",category:"think-tanks",extracto:" Liliana Alvarado, directora de Ethos, participó en la OTT Conference 2026, de On Think Tanks, uno de los encuentros internacionales más importantes para los centros de pensamiento. En este espacio, compartió experiencias sobre sostenibilidad financiera e innovación en modelos de financiamiento para los think tanks.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"En un contexto global marcado por la polarización, la desinformación y la reducción de recursos para la sociedad civil, los "},{type:b,tag:e,props:{},children:[{type:a,value:f}]},{type:a,value:" enfrentan una pregunta cada vez más urgente: ¿cómo sostener su independencia, fortalecer su credibilidad y seguir incidiendo en las decisiones públicas?"}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Con esa reflexión al centro, Ethos participó en la OTT Conference 2026, “Think Tanks and Trust”, uno de los encuentros internacionales más relevantes para los centros de pensamiento, realizado del 19 al 21 de mayo en Rabat, Marruecos, por On Think Tanks, en colaboración con el Policy Center for the New South."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"La conferencia reunió a cerca de 150 líderes y profesionales de más de 50 países para dialogar sobre los desafíos que enfrentan estas organizaciones en un entorno cada vez más complejo. Durante tres días, las conversaciones giraron en torno a la construcción de confianza pública, la reputación institucional, la resiliencia organizacional, la transparencia, la colaboración intersectorial y las nuevas formas de financiamiento."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Liliana Alvarado, directora de Ethos, participó en la sesión “Forget core funding: alternative income streams for resilient think tanks”, junto con Anthea Haryoko, del Center for Indonesian Policy Studies; Margarita Beneke de Sanfeliu, de FUSADES; y Jorge Morel Salman, del Instituto de Estudios Peruanos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El panel abordó uno de los temas más sensibles para los centros de pensamiento: cómo diversificar sus fuentes de ingreso sin comprometer su independencia ni su capacidad crítica. En un escenario en el que los modelos tradicionales de financiamiento son cada vez menos estables, la sostenibilidad financiera no puede entenderse solo como un asunto administrativo, sino como una condición para preservar la autonomía, la calidad de la evidencia y la incidencia pública."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"La participación de Ethos permitió compartir aprendizajes sobre los retos que enfrentan los "},{type:b,tag:e,props:{},children:[{type:a,value:f}]},{type:a,value:" en América Latina, así como conocer experiencias de organizaciones de distintas regiones que están explorando nuevos modelos para fortalecer su resiliencia institucional."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Más allá del intercambio de experiencias, la conferencia abrió una discusión de fondo sobre el papel que deben desempeñar los centros de pensamiento en la vida pública: producir evidencia rigurosa, construir puentes entre sectores, sostener conversaciones informadas y contribuir a que las políticas públicas respondan mejor a los desafíos sociales."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fethos_comparte_aprendizajes_sobre_sostenibilidad_financiera_en_la_ott_conference_2026",extension:".md",createdAt:g,updatedAt:g}}],fetch:{},mutations:[]}}("text","element","p","\n","em","think tanks","2026-07-19T00:56:17.206Z")));